// Тикет #6a86f7ec. В приложении вход по номеру и тестовому OTP уже автоматизирован (helpers/app.ts login()) — используем его, не дублируем.
// Шаги 4–5 (текст экрана кода, повторная отправка, неверный код) — с 03.11.2026 в specs/qa-0311/q-21, q-22 (реальное SMS, @sms).
// Код теперь 6 цифр («ספרה N מתוך שש»); вход только реальным SMS — login() ждёт человека, если OTP в accounts.env не той длины.
import { $, expect, driver } from '@wdio/globals';
import { byText, byTextContains, tapLabel, tapText, expectVisibleText, scrollToText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, login, toHome } from '../../helpers/app.ts';

/** Выход: профиль → «התנתקות» (+ подтверждение, если есть) → splash. */
async function logout() {
  await toHome();
  await tapLabel('מעבר לפרטים שלי');
  await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });
  await (await scrollToText('התנתקות')).click();
  await driver.waitUntil(async () => {
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) return true;
    const confirm = await byText('התנתקות');
    if (await confirm.isDisplayed().catch(() => false)) await confirm.click().catch(() => {});
    return false;
  }, { timeout: 20000, interval: 700, timeoutMsg: 'после «התנתקות» не открылся splash' });
}
/** Вернуться к splash/входу и войти снова (login() начинает со splash или экрана номера). */
async function restoreLogin() {
  for (let i = 0; i < 4; i++) {
    if (await isLoggedIn()) return;
    if (await byText('בואו נתחיל').isDisplayed().catch(() => false)) break;
    if (await byText('כניסה דרך מספר נייד').isDisplayed().catch(() => false)) break;
    await driver.back();
  }
  await ensureAppReady();
}

describe('Вход по мобильному', () => {
  before(async () => { await logout(); });
  after(async () => { await restoreLogin(); });

  it('AL-01 Splash → «בואו נתחיל» → экран номера (мокап, две ссылки на документы) → код → главная #6a86f7ec @prod-safe', async () => {
    // 1. Splash → «בואו נתחיל».
    await tapText('בואו נתחיל');

    // 2–3. Экран номера: заголовок, подсказка, поле с мокап-номером, две отдельные ссылки.
    await (await byText('כניסה דרך מספר נייד')).waitForDisplayed({ timeout: 20000 });
    await expectVisibleText('לקבלת קוד הזן את מספר הנייד שלך');
    const field = await (driver.isAndroid
      ? $('android=new UiSelector().className("android.widget.EditText")')
      : $('-ios class chain:**/XCUIElementTypeTextField'));
    expect(await field.getText()).toContain('0501112233');
    await expect(byTextContains('תנאי השימוש')).toBeDisplayed();
    await expect(byTextContains('מדיניות הפרטיות')).toBeDisplayed();
    await expect(byText('שילחו קוד אימות')).toBeDisplayed();

    // 4–6. Ввод номера, «שילחו קוד אימות», код → главная (login()).
    await login();
    await expect(byText('בית')).toBeDisplayed();
    await expect(byText('תזכורות מהירות')).toBeDisplayed();
  });
});
